/**
 * Typed HTTP client for the Urbanist Atlas API.
 *
 * All wire shapes (request/response bodies, enums, error envelopes) come
 * from `./api.gen.ts`, which is generated by `openapi-typescript` from
 * `../api/openapi.yaml`. Do not hand-roll types in this file — if you
 * need something new, add it to the spec and run `npm run generate:api`.
 *
 * The base URL is read from `import.meta.env.VITE_API_BASE` at build
 * time. Dev and test builds fall back to the local API server; a
 * production build without it fails at load (see {@link apiBase}).
 */
import type { components } from './api.gen.ts';

// Re-export the wire shapes that callers will commonly touch, so they
// can `import { LookupResult } from '@/lib/api'` without reaching into
// the generated file directly.
export type Country = components['schemas']['Country'];
export type Region = components['schemas']['Region'];
export type Org = components['schemas']['Org'];
export type LookupOrg = components['schemas']['LookupOrg'];
export type LookupQuery = components['schemas']['LookupQuery'];
export type LookupResult = components['schemas']['LookupResult'];
export type RegionSummary = components['schemas']['RegionSummary'];
export type RegionSearchResult = components['schemas']['RegionSearchResult'];
export type RegionSearchResultsEnvelope =
  components['schemas']['RegionSearchResultsEnvelope'];
export type RegionDetail = components['schemas']['RegionDetail'];
export type Meta = components['schemas']['Meta'];
export type RegionSummariesEnvelope = components['schemas']['RegionSummariesEnvelope'];
export type RecentEnvelope = components['schemas']['RecentEnvelope'];
export type Stats = components['schemas']['Stats'];
export type CountryStats = components['schemas']['CountryStats'];
export type Submission = components['schemas']['Submission'];
export type SubmissionPayload = components['schemas']['SubmissionPayload'];
export type NewSubmissionRequest = components['schemas']['NewSubmissionRequest'];
export type ProblemDetails = components['schemas']['ProblemDetails'];

/**
 * A country the SPA exposes to users. The wire {@link Country} is an
 * open `string` (the API accepts any code the seed data defines), so
 * the UI gates on this narrower set and a stray `?country=…` renders
 * an error instead of silently coercing.
 */
export type SupportedCountry = 'US' | 'CA';

export const SUPPORTED_COUNTRIES: readonly SupportedCountry[] = ['US', 'CA'];

/** True if `raw` is one of {@link SUPPORTED_COUNTRIES}. */
export function isSupportedCountry(raw: string): raw is SupportedCountry {
  return (SUPPORTED_COUNTRIES as readonly string[]).includes(raw);
}

const DEFAULT_API_BASE = 'http://localhost:8080';

function resolveApiBase(): string {
  const raw = import.meta.env.VITE_API_BASE;
  if (raw !== undefined && raw !== '') return raw.replace(/\/+$/, '');
  // The CSP's connect-src does not allow localhost, so a production
  // bundle on the fallback would fail every request with no clear cause.
  if (import.meta.env.PROD) {
    throw new Error(
      'VITE_API_BASE is not set. Production builds must set it to the deployed API origin (see docs/deploy.md).',
    );
  }
  return DEFAULT_API_BASE;
}

/**
 * Where the API lives, from `VITE_API_BASE` with any trailing slash
 * stripped so `${apiBase}/api/v1/…` never doubles up. Throws at module
 * load in a production build that leaves it unset or empty.
 */
export const apiBase: string = resolveApiBase();

/**
 * Canonical URL of the served OpenAPI document, derived from
 * {@link apiBase} so a QA-served build points at the QA API and a
 * production build at production. The "For developers" copy on /about,
 * the /colophon quick links, and the footer all render this — one
 * source of truth instead of three call sites (one of which used to
 * hardcode production and broke on QA builds).
 */
export const openapiUrl = `${apiBase}/api/v1/openapi.yaml`;

/**
 * Shared secret bundled into the build during Phase 1 lockdown
 * (slice #23 / CLAUDE.md § Launch strategy). The backend's
 * `URBANIST_CLIENT_SECRET` checks for the matching `X-Atlas-Client`
 * header on every `/api/v1/*` data endpoint; missing/wrong → 401.
 *
 * Empty (the default for local dev when `VITE_API_CLIENT_SECRET`
 * isn't set) means the header isn't sent — the backend's empty-
 * secret no-op preserves the dev workflow.
 */
const apiClientSecret: string = import.meta.env.VITE_API_CLIENT_SECRET ?? '';

/** Per-field validation messages from the problem+json `errors` extension. */
export type FieldErrors = Readonly<Record<string, string>>;

/**
 * Error thrown for any failed API request. `status` is the HTTP status
 * of a non-2xx response, or `0` when no response arrived (network
 * failure, CORS/CSP block, or the request timed out); the original
 * error is then kept as `cause`. `problem` is the parsed RFC 9457
 * document when the server sent one.
 *
 * `retryAfterSeconds` is the parsed `Retry-After` on a 429;
 * `fieldErrors` is the `errors` extension when present and non-empty.
 */
export class ApiError extends Error {
  readonly status: number;
  readonly problem: ProblemDetails | undefined;
  readonly requestId: string | undefined;
  readonly retryAfterSeconds: number | undefined;
  readonly fieldErrors: FieldErrors | undefined;

  constructor(
    status: number,
    message: string,
    problem: ProblemDetails | undefined,
    requestId: string | undefined,
    extras?: {
      retryAfterSeconds?: number;
      fieldErrors?: FieldErrors;
      cause?: unknown;
    },
  ) {
    super(message, extras?.cause === undefined ? undefined : { cause: extras.cause });
    this.name = 'ApiError';
    this.status = status;
    this.problem = problem;
    this.requestId = requestId;
    this.retryAfterSeconds = extras?.retryAfterSeconds;
    this.fieldErrors = extras?.fieldErrors;
  }
}

/**
 * Parses a `Retry-After` header value into a non-negative number of
 * seconds. Accepts either the delta-seconds form (an integer) or an
 * HTTP-date (RFC 9110 §5.6.7); returns `undefined` for missing,
 * malformed, or past-dated values so callers can fall back to
 * static copy.
 *
 * Exported for direct testing; the `apiFetch` path attaches the
 * parsed value to `ApiError.retryAfterSeconds`.
 */
export function parseRetryAfter(
  header: string | null,
  now: () => number = Date.now,
): number | undefined {
  if (header === null) return undefined;
  const trimmed = header.trim();
  if (trimmed === '') return undefined;
  // Delta-seconds form: "120"
  if (/^\d+$/.test(trimmed)) {
    const n = Number.parseInt(trimmed, 10);
    return Number.isFinite(n) && n >= 0 ? n : undefined;
  }
  // HTTP-date form: "Wed, 21 Oct 2026 07:28:00 GMT"
  const t = Date.parse(trimmed);
  if (Number.isNaN(t)) return undefined;
  const delta = Math.ceil((t - now()) / 1000);
  return delta > 0 ? delta : 0;
}

/**
 * Keeps only non-empty string entries of the `errors` extension: the
 * body is parsed with a cast, so its shape is not guaranteed.
 */
function extractFieldErrors(
  problem: ProblemDetails | undefined,
): FieldErrors | undefined {
  const raw: unknown = problem?.errors;
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return undefined;
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(raw)) {
    if (k !== '' && typeof v === 'string' && v !== '') out[k] = v;
  }
  return Object.keys(out).length > 0 ? out : undefined;
}

// `detail` is the occurrence-specific text the spec marks safe to show
// end users; `title` is the generic per-type summary.
function problemMessage(status: number, problem: ProblemDetails | undefined): string {
  if (problem?.detail) return problem.detail;
  if (problem?.title) return problem.title;
  return `HTTP ${status}`;
}

const REQUEST_TIMEOUT_MS = 15_000;

/**
 * Maps a rejection from `fetch` or a body read to an {@link ApiError}
 * with status 0. A caller-initiated abort is returned untouched, so
 * the caller sees its own cancellation as an AbortError.
 */
function transportError(
  err: unknown,
  callerSignal: AbortSignal | null | undefined,
  timeoutSignal: AbortSignal,
): unknown {
  if (callerSignal?.aborted) return err;
  if (timeoutSignal.aborted) {
    return new ApiError(
      0,
      'The Urbanist Atlas API timed out. Try again in a moment.',
      undefined,
      undefined,
      { cause: err },
    );
  }
  if (err instanceof SyntaxError) return err;
  return new ApiError(
    0,
    "Couldn't reach the Urbanist Atlas API. Check your connection and try again.",
    undefined,
    undefined,
    { cause: err },
  );
}

/**
 * Low-level fetch wrapper. Prepends {@link apiBase} to `path`, sets
 * `Accept: application/json`, applies a 15s timeout, and returns the
 * parsed JSON body as `T`. Throws {@link ApiError} for a non-2xx
 * response or a request that got no response; rethrows the caller's
 * own abort as-is.
 *
 * Callers should usually reach for a higher-level wrapper (e.g.
 * {@link lookup}) rather than calling this directly.
 */
export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  const headers = new Headers(init?.headers);
  if (!headers.has('Accept')) {
    headers.set('Accept', 'application/json');
  }
  if (apiClientSecret && !headers.has('X-Atlas-Client')) {
    headers.set('X-Atlas-Client', apiClientSecret);
  }

  const callerSignal = init?.signal;
  const timeoutSignal = AbortSignal.timeout(REQUEST_TIMEOUT_MS);
  const signal = callerSignal
    ? AbortSignal.any([callerSignal, timeoutSignal])
    : timeoutSignal;

  let response: Response;
  try {
    response = await fetch(`${apiBase}${path}`, { ...init, headers, signal });
  } catch (err) {
    throw transportError(err, callerSignal, timeoutSignal);
  }
  const requestId = response.headers.get('X-Request-ID') ?? undefined;

  if (!response.ok) {
    let problem: ProblemDetails | undefined;
    const contentType = response.headers.get('Content-Type') ?? '';
    if (contentType.includes('application/problem+json')) {
      try {
        problem = (await response.json()) as ProblemDetails;
      } catch {
        // An unreadable problem body still yields a bare-status error.
      }
    }
    const retryAfterSeconds =
      response.status === 429
        ? parseRetryAfter(response.headers.get('Retry-After'))
        : undefined;
    throw new ApiError(
      response.status,
      problemMessage(response.status, problem),
      problem,
      requestId,
      {
        retryAfterSeconds,
        fieldErrors: extractFieldErrors(problem),
      },
    );
  }

  try {
    return (await response.json()) as T;
  } catch (err) {
    throw transportError(err, callerSignal, timeoutSignal);
  }
}

/**
 * react-query `retry` predicate: never retries a 4xx (the request
 * itself is wrong, or rate-limited), and retries anything else once.
 */
export function shouldRetry(failureCount: number, error: unknown): boolean {
  if (error instanceof ApiError && error.status >= 400 && error.status < 500) {
    return false;
  }
  return failureCount < 1;
}

/**
 * `GET /api/v1/lookup?postal_code=…&country=…` — the main search.
 * Resolves to a {@link LookupResult} with `local` and `regional` orgs
 * for the postal code; throws {@link ApiError} on a non-2xx response
 * (including the 404 returned for unresolvable codes).
 */
export function lookup(
  postal_code: string,
  country: Country,
  init?: RequestInit,
): Promise<LookupResult> {
  const params = new URLSearchParams({ postal_code, country });
  return apiFetch<LookupResult>(`/api/v1/lookup?${params.toString()}`, init);
}

/**
 * `GET /api/v1/regions` — list the editorial default browse set
 * (metros + cities) with their approved-org counts. The endpoint
 * ships without filter parameters today; the right filter axis
 * (taxonomy via `kind`, DAG via `ancestor`, …) will be designed
 * when a concrete browse UI use case appears.
 *
 * The wire shape is `{ meta, data: RegionSummary[] }`; this helper
 * unwraps `data` so callers continue to receive the bare array.
 * Read `meta` (license, attribution_url, generated_at) by calling
 * `apiFetch<RegionSummariesEnvelope>` directly if you need it.
 */
export function listRegions(init?: RequestInit): Promise<RegionSummary[]> {
  return apiFetch<RegionSummariesEnvelope>('/api/v1/regions', init).then(
    (env) => env.data,
  );
}

/**
 * `GET /api/v1/regions/search?q=…&limit=…` — type-ahead search over
 * the full region graph (every kind, not just the browse set), ranked
 * for relevance. Each result carries a `context_label` (the nearest
 * state/province ancestor's name) for disambiguating same-named regions.
 *
 * The wire shape is `{ meta, data: RegionSearchResult[] }`; this helper
 * unwraps `data`. A blank `q` returns an empty array.
 */
export function searchRegions(
  q: string,
  limit?: number,
  init?: RequestInit,
): Promise<RegionSearchResult[]> {
  const params = new URLSearchParams({ q });
  if (limit !== undefined) params.set('limit', String(limit));
  return apiFetch<RegionSearchResultsEnvelope>(
    `/api/v1/regions/search?${params.toString()}`,
    init,
  ).then((env) => env.data);
}

/**
 * `GET /api/v1/regions/{slug}` — one region (any non-national kind)
 * plus the approved organizations that serve it (directly or via the
 * region DAG). Resolves metros, cities, counties, boroughs, states,
 * multi-state coalitions. Throws {@link ApiError} with status 404
 * when the slug is unknown or names a national-tier region.
 */
export function getRegion(slug: string, init?: RequestInit): Promise<RegionDetail> {
  return apiFetch<RegionDetail>(`/api/v1/regions/${encodeURIComponent(slug)}`, init);
}

/**
 * `GET /api/v1/orgs/{slug}` — one organization, with every region it
 * serves denormalized at `regions`. Throws {@link ApiError} with status
 * 404 when the slug isn't in the atlas (or names a non-approved org).
 *
 * Single-object response — no `{meta, data}` envelope. ODbL travels via
 * the `X-Data-License` + `X-Data-Attribution` response headers.
 */
export function getOrg(slug: string, init?: RequestInit): Promise<Org> {
  return apiFetch<Org>(`/api/v1/orgs/${encodeURIComponent(slug)}`, init);
}

/**
 * `GET /api/v1/recent` — recently approved organizations, newest
 * first. Feeds the homepage "Recently added" aside.
 *
 * The wire shape is `{ meta, data: Org[] }`; this helper unwraps
 * `data` so callers continue to receive the bare array.
 */
export function listRecent(init?: RequestInit): Promise<Org[]> {
  return apiFetch<RecentEnvelope>('/api/v1/recent', init).then((env) => env.data);
}

/**
 * `GET /api/v1/stats` — atlas-wide counts: distinct organizations,
 * regions, and the same split per country.
 *
 * Use this for every "how big is the atlas" number. Do NOT compute a
 * total by summing `direct_org_count` over {@link listRegions} —
 * `/api/v1/regions` returns only the browseable subset (metros and
 * cities), so that sum silently drops every org attached solely to a
 * state, province, borough, or multi-state region. Three components
 * did exactly that and under-reported the catalog by 30%.
 *
 * Single-object response — no `{meta, data}` envelope. ODbL travels via
 * the `X-Data-License` + `X-Data-Attribution` response headers.
 */
export function getStats(init?: RequestInit): Promise<Stats> {
  return apiFetch<Stats>('/api/v1/stats', init);
}

/**
 * `POST /api/v1/submissions` — queue an organization for editorial
 * review. The returned `Submission` carries the server-generated UUIDv7
 * `id` (echoed to the user as a short reference) and `status: 'pending'`.
 *
 * Validation errors come back as 400/422 problem documents; per-IP rate
 * limiting returns 429 with a `Retry-After` header. Callers handle the
 * three classes via `ApiError.status`.
 */
export function createSubmission(
  body: NewSubmissionRequest,
  init?: RequestInit,
): Promise<Submission> {
  const headers = new Headers(init?.headers);
  headers.set('Content-Type', 'application/json');
  return apiFetch<Submission>('/api/v1/submissions', {
    ...init,
    method: 'POST',
    headers,
    body: JSON.stringify(body),
  });
}
